{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Butorphanol, which shares the N-cyclobutylmethyl morphinan scaffold with the query, has an absolute oral bioavailability of only 5–17% in patients, directly supporting a low-F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Naltrexone, a close 4,5-epoxy morphinan with a 14-hydroxy group, shows systemic oral bioavailability of only 5–6% in healthy volunteers, supporting low oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a very close structural analogue, has an absolute oral bioavailability of 41% in humans, which argues for high bioavailability, but its 6-methylene and N-cyclopropylmethyl substituents differ from the query's 6-hydroxy and N-cyclobutylmethyl groups.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Samidorphan, another opioid antagonist analogue, shows 69% absolute oral bioavailability, but its lower similarity and different substituents limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a N-cyclobutylmethyl 4,5-epoxy morphinan with 3,6,14-triols, most closely aligned with butorphanol (same N-cyclobutylmethyl, oral F 5–17%) and naltrexone (close 4,5-epoxy morphinan, F 5–6%), both below the 20% threshold. High-F analogues such as nalmefene and samidorphan differ at key positions and are less transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the supplied evidence.",
    "The closest same-N-substituent analogue, butorphanol, lacks the 4,5-epoxy bridge, so the combined effect of the epoxy bridge and N-cyclobutylmethyl is inferred rather than directly measured.",
    "Nalmefene's high bioavailability shows that small changes at the 6-position can strongly alter oral F, adding uncertainty to extrapolation from naltrexone/butorphanol."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

